// Confirm bucket inventory
//
// Corrected 08/12/2026: the field is `display_name` (snake_case), not `displayName`, and the
// retention field is `retention_days`. The old cell failed with FIELD_DOES_NOT_EXIST.
fetch dt.system.buckets
| fields name, display_name, retention_days, dt.system.table, records
| sort name asc

// Inspect the preserved _sourceCategory equivalent
fetch logs, from:-1h, bucket:{"custom_logs_prod"}
| summarize c = count(), by:{sumo.source_category}
| sort c desc
| limit 50

// Confirm OneAgent-instrumented hosts are sending logs
fetch logs, from:-15m
| filter isNotNull(dt.entity.host)
| summarize c = count(), by:{entityName(dt.entity.host)}
| sort c desc
| limit 20

